namespace InvoiceLib;

/// <summary>
/// Ambient time provider for testability. Production code uses Clock.UtcNow;
/// tests call Clock.Override(...) to pin the clock.
/// </summary>
public static class Clock
{
    private static readonly AsyncLocal<Func<DateTimeOffset>?> s_override = new();

    public static DateTimeOffset UtcNow
        => s_override.Value?.Invoke() ?? DateTimeOffset.UtcNow;

    /// <summary>
    /// Pins the clock to <paramref name="fixedTime"/> for the current async flow.
    /// Dispose the returned scope to restore normal behavior.
    /// </summary>
    public static IDisposable Override(DateTimeOffset fixedTime)
    {
        s_override.Value = () => fixedTime;
        return new Scope();
    }

    private sealed class Scope : IDisposable
    {
        public void Dispose() => s_override.Value = null;
    }
}

